# Interstate '76 engine switches for the Steam Deck - the Deck Kit's preset (i76-everywhere deck/kit/i76-env.sh).
# Sourced by i76-deck-launch.sh at every launch. It is the owner's Deck set as measured 2026-10-25 (docs/records/DECK-2026-10-25.md):
# the PC's best-wide-balanced sim switches, the Deck's picture (16:10 Hor+, detail x8, far clip / roads 1800, TV / handheld profiles,
# pad menu), the Macs' free graphics keys, the LAN switches and the rumble shim's every-pad mode.
# DO NOT EDIT this file to tune: a kit update rewrites it. Put your own exports in i76-env.local.sh (read after this one).
export I76_HIRES_CLOCK=1
export I76_FIXED_STEP=24
export I76_FRAMERATE_FIXES=1
export I76_ENGINE_DT_FIX=1
export I76_RENDER_INTERP=1
export I76_FIX_HEALTH_PCT=1
export I76_FIX_LABEL_TABLE=1
export I76_FAR_CLIP=1800          # 1800 as on the PC: cockpit 60 fps, binoculars ~54 (2026-10-07); 1200 holds 60 everywhere
export I76_CAM_GROUND_FIX=1
export I76_ZGLIDE_TMUFIX=1          # required by MemorySizeOfTMU 8192 in dgVoodoo.conf
export I76_INPUT_LATCH=1
export I76_AI_BACKAWAY_GRID=1
export I76_GLIDE_REFRESH=60
export I76_ASPECT=1280x800          # Hor+ 16:10; HUD sprites squeezed back to shape automatically
export I76_TERRAIN_LOD=8
export I76_TERRAIN_TEX=8
export I76_OBJECT_LOD=8
export I76_SHADOW_DIST=4
export I76_ROAD_TEX=8
export I76_CLUTTER_DIST=300
export I76_MIRROR_FAR=300
export I76_COLL_DEDUPE=1
export I76_AI_ROLL_HOLD=0
export I76_GLIDE_GAMMA=1.3          # the Voodoo's default gamma: the game never sets one (needs EnableGlideGammaRamp)
export I76_CURSOR_MAP=1             # menus: pointer mapped to the stretched 640x480 page (needs CaptureMouse = false)
export I76MUSIC_LOG=1               # mciproxy.log in the game folder: proves which switches applied
export I76_DECK_AHK=0               # 1 = start the baseline AHK pad layer too (deck/setup-deck-baseline.sh)
# Game-folder DLLs Wine must prefer: dgVoodoo ddraw + d3dimm (else a 640x480 mode change pillarboxes), IPXWrapper winsock.
export WINEDLLOVERRIDES="ddraw,d3dimm,wsock32,mswsock=n,b${WINEDLLOVERRIDES:+;$WINEDLLOVERRIDES}"
# promotion 16 parity with the PC (2026-10-13): collision G + roads 1800
export I76_COLL_WINDOW=2              # collision check covers the whole physics step
export I76_COLL_WINDOW_WHEN=stepframe # ... only on the frame the car actually moves (contacts on time)
export I76_BREAKABLE_BOX=1            # barricade bars collide as the real bar, not a 3 m sphere
export I76_ROAD_DIST=1800             # roads drawn to the far clip (pool fix since promotion 8)

# --- display profiles + pad menu (deck/setup-deck-tv.sh, 2026-10-13) -----------------------------
# i76-deck-launch.sh picks a profile per launch and overrides I76_ASPECT / I76_GLIDE_GAMMA above:
# I76_ASPECT and dgVoodoo's [Glide] Resolution follow the X screen the game is given (Steam > game
# Properties > Game Resolution), the brightness values follow the profile. Each value can also be put
# in front of the wrapper in Steam's launch options, e.g.  I76_DECK_DISPLAY=handheld "/home/deck/...".
export I76_DECK_DISPLAY="${I76_DECK_DISPLAY:-auto}"            # auto (TV when an HDMI/DP display is connected) | handheld | tv | off
export I76_HANDHELD_GAMMA="${I76_HANDHELD_GAMMA:-1.3}"          # 3D gamma lift on the panel (as before)
export I76_HANDHELD_BRIGHTNESS="${I76_HANDHELD_BRIGHTNESS:-100}" # dgVoodoo Brightness on the panel (as before)
export I76_TV_GAMMA="${I76_TV_GAMMA:-1.45}"                     # 3D gamma on the TV: higher = brighter mid-tones (try 1.3 .. 1.8)
export I76_TV_BRIGHTNESS="${I76_TV_BRIGHTNESS:-100}"            # dgVoodoo Brightness on the TV, menus too (105-115 if still dark; clips highlights)
export I76_TV_CONTRAST="${I76_TV_CONTRAST:-100}"                # dgVoodoo Contrast on the TV
export I76_TV_COLOR="${I76_TV_COLOR:-100}"                      # dgVoodoo Color (saturation) on the TV
export I76_TV_SS="${I76_TV_SS:-1}"                              # render at 1x the TV size (2 = supersample, if 60 fps holds)
export I76_TV_REFRESH="${I76_TV_REFRESH:-60}"                   # TVs are 60 Hz (the OLED panel's 90 is for handheld)
export I76_PAD_MENU="${I76_PAD_MENU:-1}"                        # controller moves the menu pointer (shell + Esc menu only)
export I76_PAD_MENU_LOG="${I76_PAD_MENU_LOG:-1}"                # pad-menu lines in mciproxy.log

# --- free graphics keys (Deck lane 2026-10-25, i76-everywhere docs/records/DECK-2026-10-25.md) -----------------
# The Macs free set: terrain morph + smooth shade + the mirror set + sparse bushes. Measured on this Deck (docked, 1280x720,
# T05 standing, proxy 5d6f9828): median 60.0 / 1 % low 58.3-58.6 with them vs 60.0 / 58.2-58.9 without (n 2 each, 60 s).
export I76_TERRAIN_MORPH=0.25 I76_TERRAIN_MORPH_STATELESS=1 I76_TERRAIN_MORPH_SHADE=3 I76_TERRAIN_MORPH_NEAR=100
export I76_SHADE_SMOOTH=1
export I76_MIRROR_LOD=1 I76_MIRROR_EVERY=2 I76_MIRROR_M16=1 I76_MIRROR_M16_SKY=0 I76_MIRROR_TEX=2 I76_MIRROR_PAL=1
export I76_CLUTTER_DENSITY=0.5 I76_CLUTTER_ALPHA_FADE=150

# --- LAN switches in the main launcher (Deck lane 2026-10-25) -------------------------------------------------------
# As on the PC since 2026-10-24 (PLAY.bat = the ALL set incl. the LAN switches; owner: "ideally the main one launches
# everything"): the Steam shortcut, which starts i76-deck-launch.sh, now has them too; they act only in network games.
export I76_COOP_AI=1 I76_COOP_CHAIN=1 I76_MP_MENU=1

# --- rumble: the ffb-shim (Deck lane 2026-10-25) ---------------------------------------------------------------------------
# game/i7_sfrce.dll is the ffb-shim: rumble from the game's own force stream (shots, hits, landing, slip, engine), written to
# every connected XInput pad (the Deck's controls and a paired Xbox pad). Log: the prefix's C:\AutoHotkey\ffb-drive.log /
export I76_FFB_PADS=all
